"""Reader-facing summary, immutable raw attempt reports, plot and audit manifests."""
from dental_release.paths import expand as _release_expand
import datetime, json, hashlib, csv, time
from pathlib import Path
from lab_alarm import R, write, sha, verified
from controls import run as controls

def figure(r2, r3):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    from matplotlib.patches import Ellipse
    (fig, axs) = plt.subplots(2, 2, figsize=(12, 8.5))
    faults = r2['trials']['faults']
    names = list(faults)
    med = [faults[k]['median_measurements_among_detected'] for k in names]
    interval = np.array([faults[k]['p10_p90_measurements_among_detected'] for k in names])
    idx = np.arange(len(names))
    axs[0, 0].errorbar(med, idx, xerr=np.stack([np.array(med) - interval[:, 0], interval[:, 1] - np.array(med)]), fmt='o', capsize=4)
    axs[0, 0].set_yticks(idx, ['Weibull shift', 'Sinter ratio', 'Bad record (at #9)', 'Force model form', 'Cement-film mean'])
    axs[0, 0].set_xlim(0, 30)
    axs[0, 0].set_xlabel('Specimens to target-link alarm: median, 10-90%')
    axs[0, 0].set_title('R2 synthetic, 200 series / fault')
    axs[0, 0].grid(alpha=0.3)
    for (name, color) in [('scanner_bias', 'tab:orange'), ('true_sinter', 'tab:blue')]:
        ex = json.loads((R / 'raw' / ('EXAMPLE_R3_' + name + '.json')).read_text())
        post = ex['posterior']
        mu = np.array(post['mean'])
        C = np.array(post['covariance'])
        (v, V) = np.linalg.eigh(C)
        angle = np.degrees(np.arctan2(V[1, -1], V[0, -1]))
        axs[0, 1].add_patch(Ellipse((100 * (mu[0] - 0.8), 100 * mu[1]), width=100 * 2 * np.sqrt(5.991 * v[-1]), height=100 * 2 * np.sqrt(5.991 * v[0]), angle=angle, facecolor=color, alpha=0.4, label=name))
        axs[0, 1].plot(100 * (mu[0] - 0.8), 100 * mu[1], '.', color=color)
        truth = np.array(ex['truth'])
        axs[0, 1].plot(100 * (truth[0] - 0.8), 100 * truth[1], 'x', color=color)
    axs[0, 1].set_xlim(-0.1, 0.7)
    axs[0, 1].set_ylim(-0.1, 0.7)
    axs[0, 1].set_xlabel('Actual sinter-ratio shift (percentage points)')
    axs[0, 1].set_ylabel('Scanner bias (percentage points)')
    axs[0, 1].set_title('R3 paired port: joint posterior; x = simulated truth')
    axs[0, 1].legend(fontsize=8)
    axs[0, 1].grid(alpha=0.3)
    ext = json.loads((R / 'raw/EXTERNAL_REPLAY_R2.json').read_text())
    e = np.array([x['error_pct'] for x in ext])
    axs[1, 0].scatter(np.arange(len(e)), e, c=np.where(abs(e) > 0.5, 'tab:red', 'tab:blue'), s=10)
    axs[1, 0].axhspan(-0.5, 0.5, color='gray', alpha=0.18)
    axs[1, 0].set_title(f'External Table 2: {sum(abs(e) > 0.5)}/{len(e)} outside ±0.5 pp')
    axs[1, 0].set_xlabel('Matched material / position / direction aggregate')
    axs[1, 0].set_ylabel('Scanner - micrometer shrinkage (pp)')
    axs[1, 0].grid(alpha=0.3)
    ex = json.loads((R / 'raw/EXAMPLE_shifted_weibull.json').read_text())
    ts = [v['index'] for v in ex['timeline']]
    ys = [v['scores'].get('material_scale', {}).get('wealth', float('nan')) for v in ex['timeline']]
    axs[1, 1].semilogy(ts, ys, label='Frozen-law material-scale wealth')
    axs[1, 1].axhline(100, color='tab:red', linestyle='--', label='1 / alpha = 100')
    axs[1, 1].set_ylim(0.1, max(200, max(ys) * 2))
    axs[1, 1].set_xlabel('Specimen in acquisition order')
    axs[1, 1].set_ylabel('Test wealth (log axis)')
    axs[1, 1].set_title('Posterior updates cannot erase a frozen-law hit')
    axs[1, 1].legend(fontsize=8)
    axs[1, 1].grid(alpha=0.3)
    fig.suptitle('K50 research: incoming lab data ports — synthetic power, external metrology refutation')
    fig.tight_layout()
    fig.savefig(R / 'figures/LAB_ALARM.png', dpi=170)
    plt.close(fig)

def run():
    r2 = json.loads((R / 'raw/RESULTS_R2.json').read_text())
    r3 = json.loads((R / 'raw/RESULTS_R3.json').read_text())
    ctl = controls()
    pr2 = verified(R / 'PREREG_R2.json')
    pr3 = verified(R / 'PREREG_R3.json')
    figure(r2, r3)
    r2['gates']['independent_numeric_controls'] = all(ctl['gates'].values())
    r2['gates']['final_observation_link_localization'] = all((v['right_observation_link_fraction'] >= pr2['metrics']['correct_final_localization_fraction_min'] for v in r2['trials']['faults'].values()))
    r2['localization_criterion_scope'] = 'Correct affected observation link in the specified fixture; unique real physical root cause is UNKNOWN when candidate mechanisms share the observation.'
    results = dict(schema='X61-lab-alarm-results-v1', claim_type='capability', review_state='PENDING_INDEPENDENT_REVIEW', capability='Protocol CSV -> frozen-law observation-link alarms and joint conditional parameter/model posterior; paired length metrology separates scanner bias from sinter drift in declared tests', outcome='SCOPED_SYNTHETIC_CAPABILITY_PHYSICAL_CALIBRATION_UNKNOWN', rounds={'R1': json.loads((R / 'raw/R1_SUFFICIENCY.json').read_text()), 'R2': r2, 'R3': r3}, external_referent=r2['external_referent'], external_measurement_result=r2['external_replay'], independent_controls=ctl, physical_lab_measurements=0, claimed_novel_algorithm=False, clinical_recommendation=False, physical_sigma0_MPa='UNKNOWN until independently validated m-dependent stress-hazard map', real_false_alarm_guarantee='UNKNOWN until independently calibrated noise/null and a numerical enclosure; synthetic trials do not establish lab validity', resolution='PER_TOOTH records and paired ratios; POPULATION posterior; PHENOMENOLOGICAL closures with measurement debt', edges=[dict(source='X1b frozen design-angle family', consumer='K50 force posterior + fixed-law alarms', resolution='PER_TOOTH', timescale='HANDOVER', scope='conditional two-form force law, not physical MPa'), dict(source='Paired post/pre scanner and independent gauge', consumer='K50 sinter factor and scanner bias joint posterior', resolution='PER_TOOTH', timescale='SIMULTANEOUS', handover_consumer='future batch manufactured-state prediction', future_timescale='HANDOVER'), dict(source='Assembled-film mean', consumer='K50 cementation state', resolution='PER_TOOTH', timescale='HANDOVER', limitation='mean film not sufficient for field/hydraulic prediction'), dict(source='Raw force trace maximum and CSV endpoint', consumer='measurement_record gate', resolution='PER_TOOTH', timescale='SIMULTANEOUS')], cost=dict(R2=r2['cost'], R3=r3['cost'], human_questions=0, physical_acquisition_fit_discovery_and_fallback='UNKNOWN; no invented lab hours/cost', prior_reused_prefix='X1b FE/frozen ratios and X14 source extraction, historical compute costs not recovered'), full_cost_note='Script runtime measures new numerical replay; orientation/source search and previous failed run separately logged, not included as zero', largest_remaining_binder='Validated specimen stress hazard/contact/support and independently calibrated instrument likelihood/covariance, including common systematic bias', next_construction='Independent gauge calibration with common-bias state plus m-dependent crown stress hazard operator; freeze new held-batch predictions before physical assay')
    if (R / 'raw/INTEGRATED_CLI_CHECKS.json').exists():
        results['integrated_CLI_checks'] = json.loads((R / 'raw/INTEGRATED_CLI_CHECKS.json').read_text())
    results['files'] = {str(p.relative_to(R)): dict(bytes=p.stat().st_size, sha256=sha(p)) for p in sorted(R.rglob('*')) if p.is_file() and (not any((x in p.parts for x in ('__pycache__',)))) and (p.name not in ('results.json', 'GRAPH_FEEDBACK.json', 'CURRENT_WORK_STATE.json')) and (p.suffix in ('.py', '.json', '.csv', '.npz', '.png'))}
    write(R / 'results.json', results)
    ex = json.loads((R / 'raw/EXAMPLE_shifted_weibull.json').read_text())['posterior']
    ext = r2['external_replay']
    fs = r2['trials']['faults']
    nr = r2['trials']['null']
    r3n = r3['nominal']
    allg = all(r2['gates'].values()) and all(r3['gates'].values())
    table = '\n'.join((f"| {name} | {v['detected']}/{v['replicates']} | {v['median_measurements_among_detected']:g} | {v['channel']} |" for (name, v) in fs.items()))
    readme = _release_expand(f"# Lab CSV -> posterior and chain alarm\n\nThe runnable capability is a specimen-resolved update and alarm path for X1b's 72-crown experiment. It scores each observation against a frozen prediction before updating a joint Weibull force-scale/model-form posterior. Separate paired length, cement-film and trace ports keep manufacturing and acquisition errors visible. **Physical crown calibration is still UNKNOWN.** All numerical power results below are synthetic. The external measurement table refutes treating scanner shrinkage as the actual sinter factor.\n\n```bash\n./run_all.sh\n```\n\nThis offline command runs 13 tests, all frozen R1/R2/R3 trials, independent controls and the figure. It uses the existing Python at `@DENTAL_PYTHON@`; override `LAB_ALARM_PYTHON` with an environment containing NumPy, SciPy and Matplotlib. One thread, no GPU, no downloads. Measured R2 numerical runtime {r2['cost']['wall_seconds']:.1f}s / {r2['cost']['max_RSS_MiB']:.1f} MiB; R3 {r3['cost']['wall_seconds']:.1f}s / {r3['cost']['max_RSS_MiB']:.1f} MiB. Initial searches/failed execution and lab costs are separately UNKNOWN.\n\n| Injected fault | Detected series | Median specimens | Correct observation link |\n|---|---:|---:|---|\n{table}\n\nR2 nominal: {nr['alarms']}/{nr['replicates']} series had any alarm through 72 observations ({100 * nr['rate']:.2f}%; binomial 95% CI {100 * nr['binomial_95CI'][0]:.2f}–{100 * nr['binomial_95CI'][1]:.2f}%). Nominal family alpha is 5% under an exact correctly specified predictive law. Code uses numerical quadrature; a global numerical enclosure is missing. Faults are fixed before trials: m 6→3 and force scale ×0.65; sinter ratio 0.800→0.806; force endpoint ×3 on specimen 9; FE family→separable; cement-film mean 60→85 µm. These are severe, declared challenges; detection of arbitrary small drift is unestablished.\n\nR3 separates scanner bias from actual sinter drift using a calibrated independent gauge. In 200 series per fault, scanner bias, actual drift and both were detected and first localized correctly in 200/200, median 4 specimens. R3 nominal: {r3n['alarms']}/{r3n['replicates']} ({100 * r3n['fraction']:.2f}%). These dedicated two-channel trials allocate 2.5% to each channel. The integrated CLI profile allocates 0.25% each within its total 5%; its exact detection counts must be read from its output, not borrowed from dedicated R3.\n\nThe 95% marginal posterior intervals covered synthetic truth in {100 * r2['posterior_checks']['coverage']['m']:.1f}% for m and {100 * r2['posterior_checks']['coverage']['scale']:.1f}% for force scale; 60 predetermined independent series. This is conditional finite-grid inference, not a validated population law. Joint particles and m–scale covariance are retained. The model certificate is `decision_cert.certify` on ONE form predicate: it does not multiply correlated parameter marginals.\n\n![Detection, paired posterior and external refutation](figures/LAB_ALARM.png)\n\n## Use an actual protocol CSV\n\n```bash\n./run_all.sh measurements.csv --output LAB_001.json\n```\n\nThe unchanged [X1b protocol](inputs/X1B_LAB_PROTOCOL.md) column names and planned specimen IDs are accepted. With no sealed lab likelihood this returns UNKNOWN and mechanism observations. Blank/invalid/duplicate records are rejected. Repeated IDs never become independent specimens. CSV rows are acquisition order; export chronological rows, not the template's design-group order. A cumulative CSV can be rerun to a new output path; replay recomputes from raw data and preserves prior output. Mixed batches halt updating the earlier batch.\n\nFor the executable synthetic example:\n\n```bash\n./run_all.sh raw/SYNTHETIC_shifted_weibull.csv --profile inputs/DEMO_PROFILE.json --sidecar raw/SYNTHETIC_shifted_weibull_SIDECAR.csv --output LAB_EXAMPLE.json\n```\n\nReplace the demo profile with an independently calibrated and hash-sealed prospective lab profile before real use. The demo is explicitly SYNTHETIC_RESEARCH_PROFILE_NOT_LAB_CALIBRATED. Sidecar joins by specimen ID. Optional channels:\n\n| Channel | Sidecar columns | Inferred quantity / missing information |\n|---|---|---|\n| Paired sintering dimensions | pre_sinter_ref_length_mm, post_sinter_ref_length_mm, sinter_ratio_sd | Ratio; alone cannot distinguish true shrink from instrument bias |\n| Independent reference gauge | gauge_sinter_ratio, gauge_sinter_sd, plus paired dimensions | With sealed paired_metrology covariance: physical ratio + scanner bias joint posterior |\n| Cement after assembly | assembled_film_mean_um, assembled_film_sd_um | Mean film only; dry marginal distance does not identify cement film |\n| Force record consistency | trace_peak_force_N, source_trace_sha256 | CSV transcription vs referenced raw trace; true sensor bias remains unknown |\n\nEach populated channel needs its own externally measured error. `source_trace_sha256` must match the protocol row's `force_trace_sha256`; the CLI binds the declared trace, but the supplied CSV alone does not authenticate raw instruments/files. Synthetic filenames/hashes are explicitly fixture identifiers. Sinter/film sidecars also require archived independently calibrated sources before an empirical claim. `inputs/DEMO_PAIRED_PROFILE.json` adds the R3 paired observation state without modifying R2's freeze. Scan/gauge errors may be correlated; covariance is supplied, not estimated from one trace.\n\nThe parameter `sigma0_force_equivalent` is a characteristic **force scale in N**. It is not material strength in MPa. Physical `sigma0_material_MPa` stays UNKNOWN unless the profile binds an INDEPENDENTLY_VALIDATED stress operator, locator/hash, exact m_grid and `sigma0_per_lambda_MPa_per_N` for that reference-area convention. Missing m-dependent stress hazard, contact/support and flaw population prevent a physical material inference; fixed FE ratio factors are a scenario closure. Failure modes/origins incompatible with intaglio tension remain in the report and block tensile-strength updates.\n\n## What does not hold\n\nThe external facit is [Materials 2025, DOI 10.3390/ma18143217, Table 2](https://doi.org/10.3390/ma18143217), read offline from the primary [JATS source](inputs/Shrinkage2025.xml) and X14's parsed table. **{ext['rejected']}/{ext['pairs']} paired scanner–micrometer aggregates ({100 * ext['rejected_fraction']:.1f}%) exceed the frozen 0.5 percentage-point tolerance**; RMSE {ext['RMSE_percentage_points']:.4f} pp, maximum {ext['max_abs_error_percentage_points']:.1f} pp. This rejects equality of those modalities; it does not prove the micrometer is truth or calibrate this lab's crown. No cell n/cross-method covariance is given. 459 source modality cells are 153 matched aggregate triples, not 459 independent specimens; 153 microscopy cells are outside the compared quantity (33.3%), retained in inputs. We did not download new data or treat synthetic fixtures as external facit.\n\nExact sufficiency witnesses: dry-gap summary identity error 0 with 0.3125mm manufactured-length difference; identical mean force with 0.5 lower-tail probability difference; identical Gaussian means/marginal variances with different joint downstream tails. R3's scalar scanner ratio identity error is 0 with true sinter-ratio difference 0.03125. Minimum additions are independent observation direction, retained distribution and shared covariance. These are constructive mathematical tests, not measurements of crowns.\n\nStrong controls: SciPy PDF/CDF plus independent integration, full-data likelihood posterior and dense GLS match within frozen 1e-10. Every named injected value/model/covariance corruption rejects. Grid refinement and quadrature probes are reported, but neither provides a rigorous global numerical/physical enclosure. Common gauge bias cannot be fixed by more repeats of the same gauge. Cement-film means cannot predict spatial hydraulic conductance; field measurements remain necessary. No clinical, fatigue-life or durable-crown inference follows.\n\nData/license: primary Materials article and its table are CC BY 4.0 (authors/title in inputs/LICENSES.json); local reuse attributed to X14. X1b computational forecasts/protocol are private research artifacts; no distribution license inferred. Synthetic examples/code are this lane's research fixtures. No patient dataset, images or personal information are used.\n\nExact freezes, full raw trial outcomes, rejection fractions, costs and source/code hashes are in [results.json](results.json). Graph admission is PENDING_INDEPENDENT_REVIEW. Full K50 coverage is a proposal; the successful existing graph dispatch is kind=define for the narrow bench observation contract.\n")
    (R / 'README_DEMO.md').write_text(readme)
    (R / 'RESULTS.md').write_text(f"Incoming crown CSV can now produce conditional joint parameter/model updates and frozen-law alarms, retaining raw specimen identity and missing measurements as UNKNOWN. Adding paired independent gauge data distinguishes scanner bias from actual sinter drift in the declared synthetic tests. External Table 2 independently rejects direct scanner-to-sinter transfer in {ext['rejected']}/{ext['pairs']} paired aggregates; physical crown calibration remains UNKNOWN.\n\n| Injected fault | Detected series | Median specimens | Observation link |\n|---|---:|---:|---|\n{table}\n\nR2: all frozen gates {('PASS' if all(r2['gates'].values()) else 'FAIL/PARTIAL')}, nominal {nr['alarms']}/{nr['replicates']} any alarms. R3: all frozen gates {('PASS' if all(r3['gates'].values()) else 'FAIL/PARTIAL')}, nominal {r3n['alarms']}/{r3n['replicates']}. Dedicated R3 bias/drift/both: 200/200 detected and correctly first localized per family, median 4. Different alpha budgets are explicit in README_DEMO.\n\n13 tests pass. Independent same-information PDF/posterior/GLS controls match; no algorithm superiority claimed. Seven R2 and three R3 deliberate corruptions reject. Exact sufficiency identities and downstream differences are in raw/R1_SUFFICIENCY.json and raw/RESULTS_R3.json. Every raw failure/log/freeze retained.\n\nLargest binder: physical sigma0 MPa requires an independently validated m-dependent stress hazard; absolute load predictions and real lab alpha remain UNKNOWN. Paired gauges still require systematic calibration; regional/mean film is insufficient for hydraulic-field inference. Numerical global error enclosure is missing. See README_DEMO.md for one-command run, fault magnitudes, uncertainty, figure, license, source/dropout/cost scope.\n")
    (R / 'HANDOFF.md').write_text(f"X61-lab-alarm completed three constructions, each preserving its freeze and handoff.\nR1: protocol-only parameter/causal localization fails exactly; original CSV does not measure true sinter, film or physical stress scale. Exact summary collision 0 with 0.3125mm length difference; force mean hides lower-tail difference 0.5; marginal posterior summaries lose covariance.\nR2: specimen-resolved finite joint Weibull force-scale/model posterior plus frozen-law alarms, independent film/ratio/trace ports. Nominal {nr['alarms']}/{nr['replicates']}, declared injected fault families 200/200 each with medians 6/5/9/15/5 (bad record occurs at 9). Seven mutations reject. External paired aggregate scan/gauge equality FAIL: 68/153 >0.5pp, RMSE 0.8889pp; no lab noise law identified.\nR3 changes acquisition: independent gauge + scanner, joint (s,b) covariance. Scalar scan ambiguity exact0, true ratio difference0.03125. Nominal9/400; drift/bias/both 200/200 and first-link localization, median4 in dedicated two-channel alpha. Integrated CSV uses stricter per-channel budget and must read own alarm times.\nRun ./run_all.sh; actual CSV without prospective profile returns UNKNOWN; synthetic CSV with DEMO_PROFILE exercises posterior. Paired profile + gauge fields exercise R3 through same CLI. Output paths must be new; batch/identity/protocol/mode guards prevent silent fit. Physical sigma0 MPa remains UNKNOWN; force-equivalent scale N is not renamed material strength.\nNEXT CONSTRUCTION: add independently calibrated common gauge-bias state and acquire validated per-specimen m-dependent stress hazard I_j(m) from matched contact/support; freeze a new held-batch physical prediction before measuring. An independent force-calibration anchor is needed to separate sensor scale from material scale. Retain spatial film/region fields for hydraulic consumers. Do not copy demographic/fixture parameters as local observations.\nGraph: original manufacturing dispatch failed on old feedback hash drift; bench experiment dispatch lacked fields; safe kind=define dispatch X61-lab-alarm-port succeeded for observation contract. No source/native graph changed. Full K50 coverage proposed separately; feedback pending independent review.\nCosts: R2 {r2['cost']['wall_seconds']:.1f}s/{r2['cost']['max_RSS_MiB']:.1f}MiB and R3 {r3['cost']['wall_seconds']:.1f}s/{r3['cost']['max_RSS_MiB']:.1f}MiB, plus source/search/initial failed run and UNKNOWN physical acquisition costs. Storage tiny, no >50MB arrays.\n")
    write(R / 'ATTEMPTS.json', [dict(round='R1', outcome='PROTOCOL_ONLY_IDENTIFIABILITY_FAIL', artifact='raw/R1_SUFFICIENCY.json', next='Orthogonal sidecar and fixed-law monitor'), dict(round='R2', outcome=r2['outcome'], artifact='raw/RESULTS_R2.json', external_negative='68/153 scan/gauge aggregates reject equality', next='Paired gauge/scanner latent bias'), dict(round='R3', outcome=r3['outcome'], artifact='raw/RESULTS_R3.json', next=results['next_construction'])])
    write(R / 'CURRENT_WORK_STATE.json', dict(lane='X61-lab-alarm', status='READY_FOR_INDEPENDENT_REVIEW', updated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), latest_gate=dict(R2=r2['gates'], R3=r3['gates']), next_operation=results['next_construction'], pending='Independent review; real matched measurements/noise/stress hazard', results_sha256=sha(R / 'results.json')))
    print(json.dumps(dict(outcome=results['outcome'], all_synthetic_gates_pass=allg, figure='figures/LAB_ALARM.png', results_sha256=sha(R / 'results.json'))))
if __name__ == '__main__':
    run()
